  'vehicle.protonm.notes': 'จรวดนำส่งขนาดหนักใช้เชื้อเพลิงไฮเปอร์โกลิก ท่อน Briz-M จุดเครื่องหลายครั้งเพื่อส่งเข้าวงโคจรถ่ายโอนค้างฟ้าและวงโคจรค้างฟ้า',
  'vehicle.angaraa5.notes': 'จรวดนำส่งแบบโมดูลใช้น้ำมันก๊าดกับออกซิเจนเหลว ท่อนแกนกลางลดแรงขับเหลือ 30% ขณะที่บูสเตอร์ URM-1 สี่ตัวยังทำงานอยู่',
  'vehicle.falcon9.notes': 'นำกลับมาใช้ใหม่ได้บางส่วน การเปิดโหมดกู้คืนบูสเตอร์จะสำรองเชื้อเพลิงไว้สำหรับการจุดเครื่องย้อนกลับและจุดเครื่องลงจอด',
  'vehicle.falconheavy.notes': 'ใช้ท่อนแกน Falcon 9 สามชุด ท่อนแกนกลางลดแรงขับจนกว่าบูสเตอร์ข้างจะแยกตัว',
  'vehicle.atlasv551.notes': 'บูสเตอร์เชื้อเพลิงแข็งห้าตัว ท่อนแกนกลางน้ำมันก๊าด-ออกซิเจนเหลว และท่อนบนไฮโดรเจน Centaur ที่มีแรงดลจำเพาะสูง เครื่องยนต์ RD-180 ลดแรงขับช่วงความดันพลวัตสูงสุด',
  'vehicle.vulcan.notes': 'ท่อนแรกใช้มีเทน-ออกซิเจนเหลว ติดบูสเตอร์เชื้อเพลิงแข็งได้ถึงหกตัว ส่วน Centaur V เป็นท่อนบนไฮโดรเจนที่ลอยรอในอวกาศได้นาน',
  'vehicle.ariane64.notes': 'ท่อนแกนกลางไฮโดรเจนพร้อมบูสเตอร์เชื้อเพลิงแข็ง P120C สี่ตัว ท่อนบน Vinci จุดเครื่องซ้ำได้สำหรับภารกิจหลายวงโคจร',
  'vehicle.vegac.notes': 'ท่อนเชื้อเพลิงแข็งสามท่อน (P120C, Zefiro 40, Zefiro 9) และท่อนขับดัน AVUM+ แบบเชื้อเพลิงเหลวที่จุดเครื่องซ้ำได้ โดย P120C ใช้ร่วมกับ Ariane 6 ในฐานะบูสเตอร์',
  'vehicle.longmarch2d.notes': 'จรวดหลักของจีนสำหรับดาวเทียมสำรวจระยะไกลในวงโคจรสัมพันธ์ดวงอาทิตย์ มีสองท่อนใช้เชื้อเพลิงไฮเปอร์โกลิก ปล่อยได้จากศูนย์ปล่อยภายในแผ่นดินทั้งสามแห่ง',
  'vehicle.longmarch3be.notes': 'จรวดหลักของจีนสำหรับวงโคจรค้างฟ้า: บูสเตอร์เชื้อเพลิงเหลวสี่ตัว สองท่อนไฮเปอร์โกลิก และท่อนที่สามไฮโดรเจน YF-75 ที่จุดเครื่องซ้ำได้',
  'vehicle.longmarch5.notes': 'จรวดขนาดหนักของจีน: ท่อนแกนกลางไฮโดรเจนพร้อมบูสเตอร์น้ำมันก๊าด-ออกซิเจนเหลวสี่ตัว',
  'vehicle.h2a202.notes': 'ปลดประจำการเมื่อ 28 มิถุนายน 2025 หลังบิน 50 เที่ยว ท่อนแกนกลางไฮโดรเจน LE-7A พร้อมบูสเตอร์ SRB-A สองตัว และท่อนบน LE-5B ที่จุดเครื่องซ้ำได้ เป็นต้นแบบโดยตรงของ H3',
  'vehicle.h3.notes': 'เครื่องยนต์ไฮโดรเจน LE-9 แบบเอ็กซ์แพนเดอร์บลีด พร้อมบูสเตอร์เชื้อเพลิงแข็ง SRB-3 สองตัว',
  'vehicle.pslvxl.notes': 'สี่ท่อนสลับระหว่างเชื้อเพลิงแข็งและเชื้อเพลิงเหลว บูสเตอร์สองในหกตัวจุดกลางอากาศที่ T+25 วินาที',
  'vehicle.electron.notes': 'จรวดขนาดเล็กโครงสร้างคาร์บอนคอมโพสิต ใช้เครื่องยนต์ Rutherford แบบปั๊มไฟฟ้า และท่อนเสริมแรงส่ง Curie',
  'vehicle.starship.notes': 'ระบบสองท่อนใช้มีเทน-ออกซิเจนเหลว นำกลับมาใช้ใหม่ได้ทั้งหมด ใช้การแยกท่อนแบบร้อน และมีช่องบรรทุกในตัว (ไม่มีครอบจมูกจรวด)',
