  'skytour.theos2.text': 'THEOS-2 อยู่ในวงโคจรสัมพันธ์กับดวงอาทิตย์ วงโคจรหมุนตามดวงอาทิตย์ปีละหนึ่งรอบ จึงข้ามเส้นศูนย์สูตรขณะมุ่งลงใต้ระหว่าง 10:00 ถึง 10:30 น. ตามเวลาท้องถิ่นเสมอ ซึ่งแสงเหมาะกับการถ่ายภาพ แต่ละรอบจะเลื่อนไปทางตะวันตกของรอบก่อนเล็กน้อยเพราะโลกหมุนอยู่ข้างใต้',
