  'skytour.weather.title': 'ดาวเทียมอุตุนิยมวิทยา ทั้งวงโคจรสูงและต่ำ',
  'skytour.weather.text': 'วงแหวนที่ระยะ 36,000 กม. คือแนววงโคจรค้างฟ้า ดาวเทียมที่นั่นโคจรหนึ่งรอบต่อวันจึงนิ่งอยู่เหนือจุดเดิม และเฝ้าดูครึ่งโลกเดิมตลอดวัน ส่วนดวงอื่นโคจรต่ำผ่านขั้วโลก เห็นทั้งโลกวันละสองครั้งและละเอียดกว่า',
  'skytour.imaging.title': 'ดาวเทียมถ่ายภาพโลก',
  'skytour.imaging.text': 'ดาวเทียมถ่ายภาพของพลเรือน เชิงพาณิชย์ และทางทหารที่เปิดเผยวงโคจร ส่วนใหญ่อยู่ในวงโคจรสัมพันธ์กับดวงอาทิตย์ที่ความสูงราว 500–800 กม. กล้องต้องใช้แสงกลางวัน ส่วนดาวเทียมเรดาร์มองทะลุเมฆและทำงานกลางคืนได้ ในระดับสำรวจสามารถดูได้ว่าดาวเทียมเหล่านี้ผ่านเหนือสถานที่หนึ่งเมื่อใด',
  'skytour.debris.title': 'กลุ่มเมฆขยะอวกาศ',
  'skytour.debris.text': 'นี่คือชิ้นส่วนของดาวเทียมอุตุนิยมวิทยา Fengyun-1C ที่ถูกทำลายด้วยการทดสอบขีปนาวุธต่อต้านดาวเทียมของจีนเมื่อมกราคม 2007 ชิ้นส่วนนับพันกระจายไปทั่ววงโคจร และเมื่อ 10 กุมภาพันธ์ 2009 ดาวเทียม Iridium 33 กับ Cosmos 2251 ชนกันด้วยความเร็ว 11.6 กม./วินาที เกิดเป็นกลุ่มขยะแบบนี้อีกกลุ่มหนึ่ง',
