  'skytour.reentry.text': 'ดาวเทียมวงโคจรต่ำถูกอากาศเบาบางหน่วงความเร็วจนตกกลับลงมา ท่อนหลักของจรวด Long March 5B หนักท่อนละ 21.6 ตัน ถูกทิ้งไว้ในวงโคจรสี่ครั้งและตกลงมาโดยควบคุมไม่ได้ภายในไม่กี่วัน แม้เหลือเวลาเพียงไม่กี่ชั่วโมง ก็บอกเวลาตกได้แค่ในช่วงราว ±20 % ของเวลาที่เหลือ',
