  'use.unit.ms': 'มิลลิวินาที',
  'thai.theos2.about': 'ดาวเทียมสำรวจโลกแห่งชาติของไทย ดำเนินการโดย สทอภ. (GISTDA) สร้างโดย Airbus Defence and Space กล้องเห็นรายละเอียดได้ถึง 50 ซม. ผ่านเส้นศูนย์สูตรขณะมุ่งลงใต้ระหว่างเวลาท้องถิ่น 10:00 ถึง 10:30 และเส้นทางซ้ำรอยทุก 26 วัน',
  'thai.theos.about': 'ดาวเทียมสำรวจโลกดวงแรกของไทย ดำเนินการโดย สทอภ. (GISTDA) สร้างโดย EADS Astrium ถ่ายภาพขาวดำ 2 ม. และภาพสี 15 ม. ผ่านเส้นศูนย์สูตรขณะมุ่งลงใต้เวลา 10:00 และเส้นทางซ้ำรอยทุก 26 วัน (369 รอบ) ยังใช้งานอยู่ในปี 2026 ในภารกิจที่ขยายเวลาออกไป',
  'thai.napa1.about': 'ดาวเทียมดวงแรกของกองทัพอากาศไทย เป็นคิวบ์แซต 6U สร้างโดย ISISPACE ประเทศเนเธอร์แลนด์ มีกล้องระยะสุ่มภาคพื้นดินราว 39 ม. สำหรับการลาดตระเวนและเฝ้าตรวจ ถูกส่งขึ้นสู่วงโคจรสูงราว 500 กม. และลดระดับลงมาเหลือราว 310 กม.',
  'thai.napa2.about': 'ดาวเทียมดวงที่สองของกองทัพอากาศไทย เป็นคิวบ์แซต 6U จาก ISISPACE เช่นกัน มีกล้องระยะสุ่มภาคพื้นดินราว 5 ม. และไฟ LED สำหรับการติดตาม โคจรในวงโคจรสัมพันธ์กับดวงอาทิตย์ 520 × 540 กม. และกลับเข้าสู่บรรยากาศเมื่อวันที่ 5 กรกฎาคม 2026',
  'thai.thaicom4.about': 'ไอพีสตาร์ ดาวเทียมบรอดแบนด์ความจุสูงดวงแรกของโลก ส่งขึ้นให้ไทยคมในปี 2005 ที่ตำแหน่ง 119.5° ตะวันออก ปัจจุบันดำเนินการโดย บริษัท โทรคมนาคมแห่งชาติ (NT)',
  'thai.thaicom6.about': 'ดาวเทียมโทรทัศน์และการสื่อสารของไทยคมที่ตำแหน่ง 78.5° ตะวันออก ใช้ตำแหน่งร่วมกับไทยคม 8 ส่งขึ้นเมื่อเดือนมกราคม 2014 ด้วยจรวด Falcon 9',
  'thai.thaicom7.about': 'ครึ่งหนึ่งของดาวเทียมหนึ่งดวง ไทยคมใช้ทรานสพอนเดอร์ 14 จาก 28 ตัวของดาวเทียมที่ AsiaSat ดำเนินการในชื่อ AsiaSat 6 ที่ตำแหน่ง 120° ตะวันออก',
  'thai.thaicom8.about': 'ดาวเทียมของไทยคมที่ตำแหน่ง 78.5° ตะวันออก คู่กับไทยคม 6 ส่งขึ้นเมื่อเดือนพฤษภาคม 2016 ด้วยจรวด Falcon 9 ซึ่งท่อนแรกลงจอดบนเรือโดรนกลางทะเล',
