  'sky.about.thai': 'THEOS-2, THEOS, NAPA-1 และดาวเทียมไทยคม แต่ละดวงทำอะไรพร้อมแหล่งอ้างอิง ดูได้ที่ ดาวเทียมทำอะไรได้บ้าง ในวงโคจรของคุณ',
  'sky.about.gnss': 'กลุ่มดาวเทียมนำทาง GPS, GLONASS, Galileo และ BeiDou: {n} ดวง',
  'sky.about.weather': 'ดาวเทียมอุตุนิยมวิทยาทั้งในวงโคจรต่ำผ่านขั้วโลกและในวงโคจรค้างฟ้า: {n} ดวง',
  'sky.about.imaging': 'ดาวเทียมสำรวจทรัพยากรโลกในแคตตาล็อกสาธารณะ (กลุ่มของ CelesTrak): ดาวเทียมถ่ายภาพของพลเรือนและเชิงพาณิชย์ เช่น Landsat, Sentinel, Pléiades, WorldView และ THEOS ดาวเทียมเรดาร์ และดาวเทียมทางทหารที่มีการเผยแพร่ชุดข้อมูลวงโคจร เช่น Yaogan ของจีน ซึ่งเป็นดาวเทียมรับรู้จากระยะไกลของรัฐบาลที่น่าจะใช้ในการลาดตระเวนทางทหารด้วย รวม {n} ดวง ดาวเทียมที่ไม่มีการเผยแพร่ชุดข้อมูลวงโคจรจะไม่อยู่ในกลุ่มนี้',
  'sky.about.debris': 'Fengyun-1C ดาวเทียมอุตุนิยมวิทยาของจีนในวงโคจร 845 × 865 กม. ถูกทำลายในการทดสอบขีปนาวุธต่อต้านดาวเทียมเมื่อ 11 มกราคม 2007 NASA เรียกกลุ่มเศษที่เกิดขึ้นว่าเป็นการปนเปื้อนวงโคจรต่ำของโลกที่เลวร้ายที่สุดครั้งเดียว เศษส่วนใหญ่อยู่ในวงโคจรที่จะคงอยู่เป็นหลายสิบหรือหลายร้อยปี ปัจจุบันยังอยู่ในแคตตาล็อก {n} ชิ้น',
