  'reentry.note': 'เป็นค่าประมาณ หน่วยงานที่ทำนายการตกกลับใช้ช่วงเวลา ±20 % ของเวลาที่เหลือ และชุดข้อมูลวงโคจรที่ใหม่กว่าจะทำให้ช่วงแคบลง เมื่อปรับค่าสัมประสิทธิ์ขีปนวิถีจากข้อมูลการติดตาม การทำนายของ ESA เองหลุดนอกช่วงนี้ราวหนึ่งในยี่สิบครั้ง แบบจำลองนี้ทำนายทรงกลมที่รู้ขนาดหกในเจ็ดลูกให้ตกเร็วกว่าจริง 8 ถึง 23 % และอีกหนึ่งลูกช้าไป 2 % และทำนายท่อนจรวด 33 จาก 66 ท่อนของปี 2023–2025 ได้ภายในช่วงเวลาจากชุดข้อมูลวงโคจรชุดแรก',
  'reentry.case.title': 'กรณีศึกษา: ท่อนจรวดหลักของ Long March 5B',
  'reentry.case.lead': 'ท่อนจรวดหลักหนัก 21.6 ตันสี่ท่อนขึ้นสู่วงโคจรพร้อมน้ำหนักบรรทุก แล้วตกลงมาโดยไม่มีการควบคุมในอีกไม่กี่วัน แต่ละท่อนทำนายจากชุดข้อมูลวงโคจรชุดแรก โดยถือเป็นทรงกระบอกหมุนคว้าง 31.7 × 5.0 ม. (พื้นที่หน้าตัดเฉลี่ย 134 ตร.ม.) C_D 2.2 แล้วเทียบกับเวลาตกที่บันทึกไว้',
