  'reentry.historyNote': 'C_D·A/m ปรับให้วงโคจรที่คำนวณจากชุดแรกสุดลดระดับลงถึงความสูงของชุดล่าสุด ณ เวลาของชุดล่าสุด แล้วทำนายต่อจากชุดล่าสุด เมื่อปรับแบบนี้จากชุดแรกและชุดสุดท้าย ทรงกลมหกในเจ็ดลูกที่รู้ขนาดได้ค่าต่ำกว่า C_D·A/m จริง 8 ถึง 26 % และอีกหนึ่งลูกสูงกว่า 2 % เพราะการปรับรวมความคลาดเคลื่อนของแบบจำลองบรรยากาศไว้ด้วย',
