  'tour.cannonFalls.text': 'นิวตันจินตนาการถึงปืนใหญ่บนภูเขาที่สูงจนอากาศไม่ต้านลูกกระสุนอีกแล้ว เมื่อยิงออกไปด้วยความเร็ว 4 กม./วินาที ลูกกระสุนตกกลับลงสู่โลกเหมือนของทุกอย่างที่ถูกขว้างออกไป แต่เพราะโลกกลม มันจึงตกไกลออกไปตามความโค้งของโลก',
  'tour.cannonOrbits.title': 'ปืนใหญ่ของนิวตัน: ตกไปรอบโลก',
  'tour.cannonOrbits.text': 'ยิงเร็วขึ้น ลูกกระสุนก็ตกไกลขึ้น ที่ความเร็วราว 7.8 กม./วินาทีจากความสูงนี้ ผิวโลกโค้งหนีลูกกระสุนเร็วเท่ากับที่มันตกพอดี มันจึงไม่มีวันตกถึงพื้น นี่แหละคือวงโคจร ลูกกระสุนยังตกอยู่ตลอดเวลา เพียงแต่ตกไปรอบโลก',
  'tour.iss.title': 'สถานีอวกาศนานาชาติ',
  'tour.iss.text': 'ที่ความสูงราว 420 กม. สถานีโคจรรอบโลกหนึ่งรอบในเวลาราวชั่วโมงครึ่ง มากกว่าสิบห้ารอบต่อวัน ด้วยความเร็ว 7.7 กม./วินาที ระนาบวงโคจรเอียงจากเส้นศูนย์สูตร 51.6° สถานีจึงผ่านเหนือทุกที่ระหว่างละติจูด 51.6° เหนือและใต้ ซึ่งเป็นที่อยู่ของผู้คนส่วนใหญ่บนโลก',
  'tour.hohmann.title': 'การโอนวงโคจรแบบโฮมันน์: จุดเครื่องยนต์สองครั้ง',
  'tour.hohmann.text': 'จากวงโคจรต่ำขึ้นไปถึงความสูงของวงโคจรค้างฟ้าใช้การจุดเครื่องยนต์สองครั้ง ครั้งแรกตามทิศการบินยืดวงกลมให้เป็นวงรีที่ปลายไกลถึง 35 786 กม. อีกครึ่งรอบต่อมาที่จุดสูงสุด ครั้งที่สองทำให้วงโคจรกลม นี่คือการโอนวงโคจรของวัลเทอร์ โฮมันน์ (ค.ศ. 1925) วิธีที่ประหยัดที่สุดด้วยการจุดเครื่องยนต์สองครั้งระหว่างวงโคจรวงกลมสองวง จาก 500 กม. ใช้ราว 3.8 กม./วินาที และใช้เวลานานกว่าห้าชั่วโมงเล็กน้อย',
  'tour.molniya.title': 'โมลนิยา: ช้าเมื่ออยู่สูง',
  'tour.molniya.text': 'วงโคจรที่สหภาพโซเวียตออกแบบเพื่อการสื่อสารในแถบเหนือสุด เป็นวงรียาวที่มีจุดไกลโลกที่สุดสูง 39 750 กม. อยู่เหนือซีกโลกเหนือ ส่วนสีคือช่วงเวลาที่เท่ากัน (กฎข้อที่ 2 ของเคปเลอร์) ดาวเทียมผ่านจุดใกล้โลกที่สุดทางใต้ในเวลาไม่ถึงชั่วโมง แล้วใช้อีกสิบเอ็ดชั่วโมงจากสิบสองชั่วโมงอยู่สูงเหนือซีกโลกเหนือ ที่ความเอียง 63.4° ซึ่งเป็นความเอียงวิกฤต ความป่องของโลกไม่หมุนจุดใกล้โลกที่สุด จุดไกลโลกที่สุดจึงอยู่ทางเหนือเสมอ',
  'tour.geo.title': 'วงโคจรค้างฟ้า: ดาวเทียมที่อยู่นิ่ง',
  'tour.geo.text': 'ที่ความสูง 35 786 กม. เหนือเส้นศูนย์สูตร ดาวเทียมโคจรหนึ่งรอบในหนึ่งวันดาราคติ (23 ชม. 56 นาที) เท่ากับเวลาที่โลกหมุนรอบตัวเองหนึ่งรอบ เมื่อมองจากพื้นโลกจึงดูอยู่นิ่ง เส้นทางบนพื้นโลกเป็นเพียงจุดเดียว ดวงนี้อยู่เหนือลองจิจูด 78.5° ตะวันออก ตำแหน่งที่ดาวเทียมไทยคมใช้ จานรับสัญญาณจึงติดตั้งหันไปทางเดียวได้ตลอด',
  'tour.sso.title': 'วงโคจรสัมพันธ์กับดวงอาทิตย์: เวลาเดิมทุกวัน',
  'tour.sso.text': 'ดาวเทียมสำรวจโลกโคจรเกือบผ่านขั้วโลก เอียงจากเส้นศูนย์สูตรราว 98° ความป่องที่เส้นศูนย์สูตรของโลกหมุนระนาบวงโคจรไปราวหนึ่งองศาต่อวัน เร็วเท่ากับที่โลกโคจรรอบดวงอาทิตย์ ดาวเทียมจึงผ่านเส้นศูนย์สูตรในเวลาท้องถิ่นเดียวกันทุกวัน (ที่นี่คือ 10:30 ขณะมุ่งขึ้นเหนือ) ภาพถ่ายทุกภาพจึงได้แสงเหมือนกัน และทุกรอบเส้นทางจะเลื่อนไปทางตะวันตกเพราะโลกหมุนอยู่ข้างใต้',
