  'build.tour.stack.title': 'จรวดคือจรวดหลายลำซ้อนกัน',
  'build.tour.stack.text': 'Saturn V ที่ส่งนักบินอพอลโลไปดวงจันทร์ คือจรวดสามลำที่ตั้งซ้อนกัน ยานอวกาศอพอลโลกับหอของระบบหนีภัยที่อยู่บนยอดคือน้ำหนักบรรทุก นับรวมอยู่ในความสูงของจรวดแต่ไม่ได้วาดไว้ในภาพนี้ แต่ละท่อนมีถังเชื้อเพลิงและเครื่องยนต์ของตัวเอง ท่อนล่างสุดจุดก่อนและยกทุกอย่างขึ้นไป เมื่อถังว่างก็แยกตัวหลุดไป แล้วท่อนถัดไปจึงจุด แตะท่อนใดก็ได้เพื่อดูเครื่องยนต์และมวลของมัน',
