  // --- D06 track B: the satellite builder (build.sat.*) ---
  'build.sat.tpl.napa2': 'NAPA-2 (คิวบ์แซต 6U)',
  'build.sat.tpl.napa2.about': 'ดาวเทียมสำรวจโลกดวงที่สองของกองทัพอากาศไทย เป็นคิวบ์แซตขนาด 6U ใช้มวล 10 กก. และขนาดตามที่เผยแพร่ วงโคจรที่บินจริง ไม่มีเครื่องยนต์ และติดเซลล์แสงอาทิตย์บนตัวดาวเทียม ส่วนภาระไฟฟ้า แบตเตอรี่ วิทยุ และกล้องเป็นค่าประมาณ',
  'build.sat.tpl.theos2': 'ดาวเทียมถ่ายภาพระดับ THEOS-2',
  'build.sat.tpl.theos2.about': 'ดาวเทียมสำรวจโลกแบบเดียวกับ THEOS-2 ของ GISTDA วงโคจรสัมพันธ์กับดวงอาทิตย์ที่ 621 กม. ภาพละเอียด 0.5 ม. อายุการใช้งานสิบปี ส่งข้อมูลย่านเอกซ์ที่ 140 เมกะบิต/วินาที (eoPortal) มวล 425 กก. เป็นตัวเลขของ eoPortal และเป็นค่าประมาณ เพราะอีกแหล่งให้ 417 กก. กล้องเป็นตัวอย่างที่ให้ 0.5 ม. ตามที่เผยแพร่ ไม่ใช่การออกแบบจริง',
  'build.sat.tpl.earthObs.about': 'ดาวเทียมสำรวจโลกประเภทหนึ่งในแค็ตตาล็อก (เช่น Resurs-P, WorldView) บนวงโคจรสัมพันธ์กับดวงอาทิตย์ที่ 600 กม. มวล เครื่องยนต์ และขนาดเป็นค่าทั่วไปของประเภทนี้ ส่วนที่เหลือเป็นค่าประมาณ',
  'build.sat.tpl.comsat.about': 'ดาวเทียมสื่อสารค้างฟ้าประเภทหนึ่งในแค็ตตาล็อก (เช่น Express-AM, Intelsat) พร้อมเครื่องยนต์จุดไกลโลกที่สุดสำหรับขึ้นจากวงโคจรถ่ายโอน มวล เครื่องยนต์ และขนาดเป็นค่าทั่วไปของประเภทนี้ ส่วนที่เหลือเป็นค่าประมาณ',
  'build.sat.tpl.weather.about': 'ดาวเทียมอุตุนิยมวิทยาค้างฟ้าประเภทหนึ่งในแค็ตตาล็อก (เช่น Elektro-L, GOES) พร้อมเครื่องยนต์จุดไกลโลกที่สุด มวล เครื่องยนต์ และขนาดเป็นค่าทั่วไปของประเภทนี้ ส่วนที่เหลือเป็นค่าประมาณ',
  'build.sat.tpl.navigation.about': 'ดาวเทียมนำทางประเภทหนึ่งในแค็ตตาล็อก (เช่น GLONASS-K, GPS III) บนวงโคจรของ GLONASS ที่ 19 130 กม. มวล เครื่องยนต์ และขนาดเป็นค่าทั่วไปของประเภทนี้ ส่วนที่เหลือเป็นค่าประมาณ',
