  'watch.say.stagingFailure': 'แกนกลางปล่อยขั้นบนไม่หลุดหมด ขั้นบนจุดเครื่องทั้งที่ยังติดอยู่ด้านหนึ่ง จรวดจึงเบี่ยงออกนอกเส้นทาง',
