  'watch.say.abortFairing': 'หอถูกปลดทิ้งไปตั้งแต่นาทีที่สอง มอเตอร์สี่ตัวบนครอบหัวจึงทำหน้าที่แทน ดึงส่วนหัวที่มีลูกเรือออกห่างจากจรวดที่พัง',
