  'watch.say.escapeCoast': 'มอเตอร์ดับแล้ว ครีบตาข่ายบนครอบหัวกางออกเพื่อให้ส่วนหัวพุ่งเอาหัวนำขณะไต่ขึ้นด้วยความเร็วที่ได้มา',
  'watch.say.escapeCapsule': 'แคปซูลลงจอดที่มีลูกเรืออยู่ข้างในหลุดออกทางด้านล่างของครอบหัว ส่วนที่เหลือถูกทิ้งไว้',
  'watch.say.escapeModules': 'แคปซูลลงจอดที่มีลูกเรืออยู่ข้างในแยกตัวออกจากโมดูลโคจรและโมดูลบริการ มีเพียงส่วนนี้เท่านั้นที่ออกแบบมาให้กลับผ่านชั้นบรรยากาศได้',
  'watch.say.ballistic': 'ไม่มีเวลาให้บังคับทิศ แคปซูลจึงตกลงมาโดยไม่มีแรงยก เหมือนก้อนหินที่ถูกขว้าง อากาศเบรกมันอย่างแรง ลูกเรือรับแรงหลายเท่าของน้ำหนักตัว',
