  'watch.say.mainChute': 'ร่มหลักขนาดพันตารางเมตรกางออกเป็นขั้น ๆ เพื่อให้แรงกระชากยังทนได้',
  'watch.say.mainDescent': 'ร่อนลงอย่างเงียบ ๆ ด้วยความเร็วราวเจ็ดเมตรต่อวินาที แผ่นกันความร้อนถูกปลดทิ้งเพื่อเปิดจรวดลงจอดนุ่มนวล',
