  // --- G08 ---
  'setup.faults.title': 'ความล้มเหลวของระบบควบคุม (G08)',
  'setup.faults.note': 'ทำให้แอคชูเอเตอร์ เซนเซอร์ หรือคอมพิวเตอร์การบินของระบบควบคุมท่าทางล้มเหลวตามเวลาที่กำหนด หรือจำลองอุบัติเหตุจริง แล้วดูว่า FDIR ช่วยเที่ยวบินไว้ได้หรือไม่ ถ้าไม่มีรายการ จะไม่มีอะไรล้มเหลวและเที่ยวบินเหมือนเดิมทุกประการ',
  'setup.faults.preset': 'สถานการณ์',
  'setup.faults.preset.none': 'ไม่มี',
  'setup.faults.preset.custom': 'กำหนดเอง',
  'setup.faults.preset.proton2013': 'Proton-M, 2 ก.ค. 2013',
  'setup.faults.preset.ariane501': 'Ariane 501, 4 มิ.ย. 1996',
  'setup.faults.preset.vega17': 'Vega VV17, 17 พ.ย. 2020',
  'setup.faults.preset.falconGimbal': 'หัวฉีดค้างสุดทาง (สมมติ)',
  'setup.faults.presetNote.proton2013': 'เซนเซอร์วัดอัตราเชิงมุมแกนหันเห (yaw) สามตัวถูกติดตั้งกลับหัว สัญญาณป้อนกลับอัตราของระบบควบคุมจึงผลักแทนที่จะหน่วง จรวดเบี่ยงในแกนหันเหทันทีหลังขึ้นจากฐานและตกใกล้ฐานปล่อย เซนเซอร์ทั้งสามผิดแบบเดียวกัน การโหวตจึงช่วยอะไรไม่ได้ จำลองบน Proton-M โดยกลับทิศแกนหันเหใน IMU ทั้งสามชุดตั้งแต่ขึ้นจากฐาน',
  'setup.faults.presetNote.ariane501': 'ระบบอ้างอิงเฉื่อยทั้งสองชุดใช้ซอฟต์แวร์เดียวกัน การแปลงเลข 64 บิตเป็น 16 บิตที่ไม่มีการป้องกันเกิดล้นที่ประมาณ H0+37 วินาที ทั้งสองชุดดับ คอมพิวเตอร์บนยานอ่านข้อมูลวินิจฉัยของมันเป็นค่าท่าทาง แล้วสั่งหัวฉีดไปจนสุดทาง จรวดแตกด้วยแรงอากาศพลศาสตร์ จำลองบน Ariane 6 ซึ่งใกล้เคียงที่สุดในกลุ่มยาน โดยทำให้ IMU ทั้งสามชุดล้มเหลวที่ T+36.7 วินาที',
  'setup.faults.presetNote.vega17': 'สายไฟของแอคชูเอเตอร์หัวฉีดสองตัวของขั้นบน AVUM ถูกต่อสลับกันตอนประกอบ ตั้งแต่ขั้นนี้จุดครั้งแรก หัวฉีดเคลื่อนสวนทางทุกคำสั่ง และขั้นก็หมุนควง ตัวเฝ้าดูของ FDIR เห็นแอคชูเอเตอร์ทำตามสิ่งที่ได้รับ จึงไม่พบอะไรผิด แบบจำลองกลับทิศหัวฉีดของ AVUM+ เมื่อขั้นที่ 4 เริ่มบิน',
  'setup.faults.presetNote.falconGimbal': 'ไม่ใช่อุบัติเหตุจริง: หัวฉีดของเครื่องยนต์วงนอกเครื่องหนึ่งของ Falcon 9 ถูกขับไปจนสุดทางที่ T+60 วินาที ถ้าไม่มี FDIR อีกแปดเครื่องต้องสู้กับมัน ถ้ามี FDIR ตัวเฝ้าดู gimbal จะดับเครื่องนั้นภายใน 0.3 วินาที แล้วเครื่องที่เหลือบังคับทิศต่อไป เหมือนที่ Falcon 9 บินต่อหลังเครื่องยนต์ดับในเที่ยวบิน CRS-1 ปี 2012',
