  'setup.faults.fdirNote': 'โหวต IMU (2 ใน 3); แบบจำลองของแอคชูเอเตอร์หัวฉีดทุกตัว และดับเครื่องยนต์ที่หัวฉีดเสีย; แยกเจ็ต RCS ที่เสีย; และคอมพิวเตอร์การบินสำรองที่รับช่วงภายใน 0.2 วินาที ถ้าปิด คอมพิวเตอร์อ่าน IMU 1 ชุดเดียวและไม่เฝ้าดูอะไรเลย',
