  'setup.explicit.title': 'การนำทางขาขึ้น: PEG และ IGM (G01)',
  'setup.explicit.note': 'ขั้นแรกบินตามโปรแกรม pitch เหมือนเดิม ส่วนขั้นที่พ้นบรรยากาศแล้วใช้กฎแบบชัดแจ้ง (explicit) นำเข้าสู่วงโคจรส่งได้ โดยคุมความสูงและความเร็วที่จุดใกล้โลกที่สุด เส้นทางบินในแนวระดับ และระนาบวงโคจร',
  'setup.explicit.law': 'การนำทางของขั้นบน',
  'setup.explicit.standard': 'แบบมาตรฐาน (วงปิด linear tangent)',
  'setup.explicit.peg': 'PEG — Powered Explicit Guidance ของกระสวยอวกาศ',
  'setup.explicit.igm': 'IGM — Iterative Guidance Mode ของ Saturn V',
  'setup.explicit.about.standard': 'การบังคับทิศแบบวงปิดของโปรแกรมเอง: ช่องแนวดิ่งแบบ linear tangent ที่มีขีดจำกัด และป้อนกลับแกนหันเหให้เข้าระนาบ',
  'setup.explicit.about.peg': 'เก็บค่าความเร็วที่ต้องเพิ่ม (v_go) ต่อจากรอบก่อน แล้วแก้ด้วยการทำนายสถานะตอนดับเครื่อง ซึ่งอินทิเกรตรวมแรงโน้มถ่วง J2 และขั้นที่เหลือ',
  'setup.explicit.about.igm': 'แก้สมการรูปปิดในกรอบอ้างอิงที่จุดดับเครื่องที่ทำนายไว้ ใช้แรงโน้มถ่วงเฉลี่ยระหว่างตอนนี้กับที่เป้า และใน 20 วินาทีสุดท้ายบังคับทิศตามความเร็วอย่างเดียว',
  'setup.explicit.cycle': 'รอบการคำนวณ (วินาที)',
  'setup.explicit.engage': 'เริ่มควบคุมเมื่อขั้นถัดไปจุดแล้ว หรือขั้นแรกพ้นบรรยากาศ (ต่ำกว่า 100 Pa ที่ความสูงเกิน 70 กม.) ถ้าขั้นที่เหลือไปไม่ถึงเป้า จะคืนการควบคุมให้การนำทางแบบมาตรฐาน ในโหมด 6-DOF ยังปล่อย load relief ขาขึ้นที่ 4 °/วินาที แทนการปล่อยทีเดียวที่ 500 Pa',
